/**
 * worker.mjs — ApexLogics MCP Server (Cloudflare Worker)
 * Endpoint: https://mcp.apexlogics.org/mcp
 *
 * Uses McpServer (SDK 1.29.0) for tool registration + protocol compliance.
 * Uses a custom StatelessFetchTransport that bridges the CF Workers Fetch API
 * to the SDK's Transport interface without requiring fetch-to-node or Node.js
 * ServerResponse. Each request gets a fresh server instance (stateless).
 *
 * Data fixtures are pre-generated by generate.mjs and bundled at deploy time.
 */

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { TOOL_SCHEMAS } from "./pilot.mjs";
import { executionHash } from "./_hash.mjs";
import { runChain } from "./run_chain.mjs";
import toolsData from "./data/tools.json" with { type: "json" };
import workflowsData from "./data/workflows.json" with { type: "json" };
import chaingraphData from "./data/chaingraph/chaingraph.json" with { type: "json" };

const SERVER_META = { name: "apexlogics-tools", version: "1.4.0" };

// ── OCG Standard §4 — execution-hash verification ────────────────────────────
// Preimage canonicalization is the vendored SSOT _hash.mjs (RFC 8785 JCS +
// SHA-256 over {policy_parameters, output_payload}). executionHash() returns
// BARE lowercase hex — byte-identical to AINumbers/OCS so any artifact verifies
// anywhere. CUTOVER 2026-07-04: pre-cutover ApexLogics artifacts carried a
// "sha256:" prefix on the SAME hex payload; normHash() strips the optional
// prefix on BOTH sides so OLD (prefixed) and NEW (bare) artifacts both verify
// through one code path. See CHAINGRAPH-ADOPTION.md hash-cutover note.
const normHash = (h) => (typeof h === "string" ? h.replace(/^sha256:/, "") : h);

// ── Discovery layer — BM25 over the catalog (find_tool) and chains (find_chain) ─
// Index built once at module load (123 tools + 38 chains — cheap; no precomputed
// data file, so nothing to keep fresh). Workers-runtime safe: plain arithmetic only.
// Ported from the AINumbers mcp-apps-poc discovery region (SSOT reference; not forked).
function tokenizeForIndex(text) {
  return (text ?? "").toLowerCase()
    .replace(/[^a-z0-9_-]/g, " ")
    .split(/\s+/)
    .filter((t) => t.length > 1);
}

function buildIndex(docs, getText) {
  const N = docs.length;
  const tfs = docs.map((doc) => {
    const counts = {};
    for (const t of tokenizeForIndex(getText(doc))) counts[t] = (counts[t] || 0) + 1;
    return counts;
  });
  const docLengths = tfs.map((tf) => Object.values(tf).reduce((s, c) => s + c, 0));
  const avgDocLength = docLengths.reduce((s, c) => s + c, 0) / N || 1;
  const df = {};
  for (const tf of tfs) for (const t of Object.keys(tf)) df[t] = (df[t] || 0) + 1;
  const idf = {};
  for (const [t, f] of Object.entries(df)) idf[t] = Math.log((N - f + 0.5) / (f + 0.5) + 1);
  return { docs, tfs, docLengths, avgDocLength, idf };
}

function bm25Search(query, index, { k1 = 1.2, b = 0.75, topN = 5 } = {}) {
  const terms = tokenizeForIndex(query);
  if (!terms.length) return [];
  const { docs, tfs, docLengths, avgDocLength, idf } = index;
  const scores = new Array(docs.length).fill(0);
  for (const t of terms) {
    const idfScore = idf[t] ?? 0;
    if (!idfScore) continue;
    for (let i = 0; i < docs.length; i++) {
      const tf = tfs[i][t] ?? 0;
      if (!tf) continue;
      scores[i] += idfScore * (tf * (k1 + 1)) / (tf + k1 * (1 - b + b * docLengths[i] / avgDocLength));
    }
  }
  return docs
    .map((doc, i) => ({ doc, score: scores[i] }))
    .filter((r) => r.score > 0)
    .sort((a, c) => c.score - a.score)
    .slice(0, topN);
}

const TOOL_INDEX = buildIndex(toolsData, (t) =>
  [t.title, t.description, t.category, t.al_id, t.slug].filter(Boolean).join(" ")
);
const CHAIN_INDEX = buildIndex(chaingraphData.chains ?? [], (c) =>
  [c.name, c.title, c.persona, ...(c.steps ?? []).map((s) => s.tool_id)].filter(Boolean).join(" ")
);

// ── StatelessFetchTransport ───────────────────────────────────────────────────
// Bridges the CF Workers Fetch API to the MCP SDK Transport interface.
// Each instance handles exactly one request/response cycle.
// The SDK calls send() with the response; handleRequest() waits for it.

class StatelessFetchTransport {
  _pending = new Map();
  onmessage = null;
  onerror = null;
  onclose = null;

  async start() {}
  async close() {}

  // Called by McpServer to deliver a response or notification
  async send(message) {
    const id = message?.id;
    if (id !== undefined && id !== null) {
      const resolve = this._pending.get(String(id));
      if (resolve) {
        resolve(message);
        this._pending.delete(String(id));
      }
    }
  }

  // Entry point from the fetch handler
  async handleRequest(req) {
    let body;
    try {
      body = await req.json();
    } catch {
      return Response.json(
        { jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } },
        { status: 400, headers: CORS_HEADERS }
      );
    }

    // Notifications have no id — deliver and return 204
    if (body.id === undefined || body.id === null) {
      this.onmessage?.(body);
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    // Requests — register response promise BEFORE delivering message
    const responsePromise = new Promise((resolve, reject) => {
      const timer = setTimeout(
        () => reject(new Error(`MCP timeout: no response for id=${body.id} method=${body.method}`)),
        10000
      );
      this._pending.set(String(body.id), (msg) => {
        clearTimeout(timer);
        resolve(msg);
      });
    });

    try {
      this.onmessage?.(body);
    } catch (e) {
      this._pending.delete(String(body.id));
      return Response.json(
        { jsonrpc: "2.0", id: body.id, error: { code: -32603, message: e.message } },
        { status: 500, headers: CORS_HEADERS }
      );
    }

    const response = await responsePromise;
    return Response.json(response, { headers: CORS_HEADERS });
  }
}

// ── CORS ─────────────────────────────────────────────────────────────────────

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Accept, MCP-Protocol-Version, Mcp-Session-Id",
  "Access-Control-Expose-Headers": "Mcp-Session-Id",
};

// ── Tool handlers ─────────────────────────────────────────────────────────────

function handleListTools({ query, category, limit = 20 }) {
  const q = (query || "").toLowerCase().trim();
  const cat = (category || "").toLowerCase().trim();
  const lim = Math.min(limit, 50);

  let results = toolsData.filter((t) => {
    if (cat && t.category !== cat) return false;
    if (!q) return true;
    const hay = [t.title, t.description, t.al_id, t.slug, t.category]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return q.split(/\s+/).every((term) => hay.includes(term));
  });

  const total = results.length;
  results = results.slice(0, lim);

  return {
    query: q || null,
    category: cat || null,
    total_matches: total,
    returned: results.length,
    tools: results.map((t) => ({
      al_id: t.al_id,
      title: t.title,
      description: t.description,
      category: t.category,
      url: `https://apexlogics.org/tools/${t.slug}/`,
      ap2_type: t.ap2_mandate_type,
      ap2_export: t.ap2_export,
    })),
    _note: total > lim ? `${total - lim} more — refine query or increase limit (max 50)` : null,
  };
}

function handleBuildWorkflow({ workflow }) {
  const name = (workflow || "").toLowerCase().trim();

  if (!name) {
    return {
      available_workflows: Object.entries(workflowsData).map(([id, w]) => ({
        id,
        description: w.description,
        steps: w.steps.length,
      })),
      usage: 'Pass workflow: "<id>" to get ordered deep-links for that chain.',
    };
  }

  const wf = workflowsData[name];
  if (!wf) {
    return { error: `Unknown workflow: "${name}"`, available: Object.keys(workflowsData) };
  }

  return {
    workflow: name,
    description: wf.description,
    workflow_page: `https://apexlogics.org/workflows/${name}.html`,
    steps: wf.steps.map((s, i) => ({
      step: i + 1,
      tool: s.tool,
      note: s.note,
      url: `https://apexlogics.org/tools/${s.tool}/`,
    })),
    _tip: "Run steps in order. Each tool exports an AP2 mandate you can paste into the next tool's import field.",
  };
}

// run_chain — OCG Standard §21. Execute a named chain server-side and return the
// composite artifact + reproducible composite_execution_hash. Omit chain to list
// runnable chains. Non-kernel steps degrade to no_kernel_browser_only (not an error).
async function handleRunChain({ chain, inputs }) {
  const name = (chain || "").trim();
  if (!name) {
    return {
      available_chains: (chaingraphData.chains ?? []).map((c) => ({
        name: c.name,
        title: c.title ?? c.name,
        steps: (c.steps ?? []).length,
      })),
      usage: 'Pass chain: "<name>" to run it server-side. Optionally pass inputs: { "<tool_id>": { ...fields } }.',
    };
  }
  try {
    return await runChain(name, inputs);
  } catch (e) {
    return {
      error: e.message,
      available: (chaingraphData.chains ?? []).map((c) => c.name),
    };
  }
}

// find_tool — ranked BM25 over the tool catalog. For a single calculator; use
// find_chain for multi-step journeys, list_apexlogics_tools for the full list.
function handleFindTool({ query, top_n = 5 }) {
  const q = (query || "").trim();
  const topN = Math.min(Math.max(top_n || 5, 1), 10);
  if (!q) return { error: "Provide a query.", hint: "e.g. 'ISO AMT exposure' or 'teacher pension'." };
  const hits = bm25Search(q, TOOL_INDEX, { topN });
  if (!hits.length) {
    return { query: q, results: [], hint: "No tool matched. Try find_chain for a multi-step goal or list_apexlogics_tools for the full catalog." };
  }
  return {
    query: q,
    returned: hits.length,
    results: hits.map(({ doc: t, score }) => ({
      al_id: t.al_id,
      title: t.title,
      description: t.description,
      category: t.category,
      url: `https://apexlogics.org/tools/${t.slug}/`,
      ap2_type: t.ap2_mandate_type,
      ap2_export: t.ap2_export,
      score: Math.round(score * 1000) / 1000,
    })),
    _tip: "Run a multi-tool journey with find_chain / run_chain.",
  };
}

// find_chain — ranked BM25 over the catalog chains. For multi-step journeys; run a
// match server-side with run_chain, or build_workflow_links for deep-link pages.
function handleFindChain({ query, top_n = 5 }) {
  const q = (query || "").trim();
  const topN = Math.min(Math.max(top_n || 5, 1), 10);
  if (!q) return { error: "Provide a query.", hint: "e.g. 'career pivot' or 'equity exit 83b'." };
  const hits = bm25Search(q, CHAIN_INDEX, { topN });
  if (!hits.length) {
    return { query: q, results: [], hint: "No chain matched. Try find_tool for a single calculator." };
  }
  return {
    query: q,
    returned: hits.length,
    results: hits.map(({ doc: c, score }) => ({
      name: c.name,
      title: c.title ?? c.name,
      persona: c.persona ?? null,
      steps: (c.steps ?? []).map((s) => s.tool_id),
      run: `run_chain(chain: "${c.name}")`,
      score: Math.round(score * 1000) / 1000,
    })),
    _tip: "Execute a match server-side with run_chain, passing its name.",
  };
}

// ── Server factory (new instance per request — stateless) ────────────────────

function buildServer(env) {
  const server = new McpServer({
    ...SERVER_META,
    instructions:
      `ApexLogics is a ${toolsData.length}-tool edtech and careertech suite. Use find_tool for a ranked search when you need one specific calculator, find_chain for a ranked search when the goal spans several tools, and run_chain to execute a chain server-side. list_apexlogics_tools returns the full unranked catalog; build_workflow_links returns deep-link workflow pages.`,
  });

  server.tool(
    "find_tool",
    TOOL_SCHEMAS.find_tool.description,
    TOOL_SCHEMAS.find_tool.params,
    async (args) => {
      return { content: [{ type: "text", text: JSON.stringify(handleFindTool(args), null, 2) }] };
    }
  );

  server.tool(
    "find_chain",
    TOOL_SCHEMAS.find_chain.description,
    TOOL_SCHEMAS.find_chain.params,
    async (args) => {
      return { content: [{ type: "text", text: JSON.stringify(handleFindChain(args), null, 2) }] };
    }
  );

  server.tool(
    "list_apexlogics_tools",
    TOOL_SCHEMAS.list_apexlogics_tools.description.replace("{COUNT}", String(toolsData.length)),
    TOOL_SCHEMAS.list_apexlogics_tools.params,
    async (args) => {
      return { content: [{ type: "text", text: JSON.stringify(handleListTools(args), null, 2) }] };
    }
  );

  server.tool(
    "build_workflow_links",
    TOOL_SCHEMAS.build_workflow_links.description,
    TOOL_SCHEMAS.build_workflow_links.params,
    async (args) => {
      return { content: [{ type: "text", text: JSON.stringify(handleBuildWorkflow(args), null, 2) }] };
    }
  );

  // verify_execution_hash — OCG Standard §4. Recompute an artifact's execution
  // hash so any agent can independently verify an ApexLogics (or any OCG
  // vendor's) artifact rather than trust it. Vendor-neutral: bare-hex JCS.
  // Normalizes the optional "sha256:" prefix so pre-2026-07-04 (prefixed) and
  // post-cutover (bare) ApexLogics artifacts both verify.
  server.tool(
    "verify_execution_hash",
    TOOL_SCHEMAS.verify_execution_hash.description,
    TOOL_SCHEMAS.verify_execution_hash.params,
    async (args) => {
      const a = args.artifact;
      const pp = args.policy_parameters ?? a?.policy_parameters;
      const op = args.output_payload ?? a?.output_payload;
      const claimed = args.claimed_hash ?? a?.execution_hash ?? null;
      if (pp === undefined || op === undefined) {
        return { content: [{ type: "text", text: "Provide a full artifact, or policy_parameters + output_payload (+ claimed_hash)." }] };
      }
      let computed;
      try {
        computed = await executionHash(pp, op);
      } catch (e) {
        // _hash.mjs assertIJson() rejects non-finite / unsafe-integer values
        // rather than emit an unstable hash — report, do not 500.
        return { content: [{ type: "text", text: JSON.stringify({
          valid: false,
          error: "non-canonical-input",
          detail: e.message,
          note: "policy_parameters/output_payload contain a value outside I-JSON (NaN/Infinity or an integer beyond 2^53). Not hashable under OCG §4; treat as unverified.",
          spec: "OCG Standard §4 (RFC 8785 JCS + SHA-256)",
        }, null, 2) }] };
      }
      const valid = claimed != null && normHash(computed) === normHash(claimed);
      const out = {
        valid,
        computed_hash: computed,
        claimed_hash: claimed,
        tool_id: a?.tool_id ?? null,
        chaingraph_version: a?.chaingraph_version ?? a?.ap2_version ?? null,
        note: claimed == null
          ? "No claimed hash supplied — returning the computed hash only (bare hex, OCG §4)."
          : (valid ? "Verified: recomputed hash matches the artifact (sha256: prefix normalized)." : "MISMATCH: treat the artifact as unverified."),
        spec: "OCG Standard §4 (RFC 8785 JCS + SHA-256)",
      };
      return { content: [{ type: "text", text: JSON.stringify(out, null, 2) }] };
    }
  );

  server.tool(
    "run_chain",
    TOOL_SCHEMAS.run_chain.description,
    TOOL_SCHEMAS.run_chain.params,
    async (args) => {
      return { content: [{ type: "text", text: JSON.stringify(await handleRunChain(args), null, 2) }] };
    }
  );

  return server;
}

// ── Fetch handler ─────────────────────────────────────────────────────────────

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    if (url.pathname === "/healthz" || url.pathname === "/") {
      return Response.json(
        { status: "ok", server: SERVER_META, tools: Object.keys(TOOL_SCHEMAS) },
        { headers: CORS_HEADERS }
      );
    }

    // Agent-directory / MCP-client discovery: served over plain GET before connecting.
    if (url.pathname === "/.well-known/mcp/server-card.json") {
      return Response.json(
        {
          schema_version: "mcp-server-card-v1",
          name: "apexlogics-mcp",
          title: "ApexLogics MCP",
          description:
            `Live MCP endpoint for the ApexLogics edtech and careertech suite: ${toolsData.length} deterministic, privacy-first calculators plus chainable OpenChainGraph compute nodes with verifiable SHA-256 execution hashes. Ranked catalog search (find_tool / find_chain) and server-side chain execution (run_chain). Zero PII, zero network after page load, zero payload logging.`,
          version: SERVER_META.version,
          publisher: { name: "Post Oak Labs", url: "https://postoaklabs.com" },
          license: "CC-BY-4.0",
          endpoints: [
            { url: "https://mcp.apexlogics.org/mcp", transport: "streamable-http", protocol_version: "2025-06-18", authentication: "none" },
          ],
          capabilities: { tools: {}, resources: {}, prompts: {} },
          registry: "org.apexlogics/tools",
          documentation: "https://apexlogics.org/about.html",
          standard: "https://ainumbers.co/chaingraph/openchain-graph-spec.html",
          llms_txt: "https://apexlogics.org/llms.txt",
        },
        { headers: { ...CORS_HEADERS, "Cache-Control": "public, max-age=3600" } }
      );
    }

    if (url.pathname === "/mcp") {
      if (request.method !== "POST") {
        return Response.json({ error: "POST required" }, { status: 405, headers: CORS_HEADERS });
      }

      // Parse a clone for telemetry — the transport consumes the original request stream.
      // Structural metadata only; never payloads, parameters, or outputs.
      const body = await request.clone().json().catch(() => undefined);
      const isToolCall = body?.method === "tools/call";
      const toolName   = isToolCall ? (body?.params?.name ?? "unknown") : null;
      const chainDepth = isToolCall ? (body?.params?.arguments?.chain_depth ?? 0) : null;
      const t0 = Date.now();

      try {
        const transport = new StatelessFetchTransport();
        const server = buildServer(env);
        await server.connect(transport);
        const response = await transport.handleRequest(request);

        // Fire-and-forget Analytics Engine telemetry — never blocks the response.
        // Salted, non-reversible caller hash (no PII). Mirrors ainumbers-mcp / ocs-mcp.
        if (isToolCall && env.ANALYTICS) {
          const latencyMs = Date.now() - t0;
          const success   = response.status < 500;
          const callerRaw = request.headers.get("CF-Connecting-IP") ?? request.headers.get("X-Forwarded-For") ?? "";
          const callerBuf = await crypto.subtle.digest("SHA-256",
            new TextEncoder().encode("apexlogics-mcp-v1:" + callerRaw));
          const callerHash = "sha256:" + Array.from(new Uint8Array(callerBuf)).map(b => b.toString(16).padStart(2, "0")).join("").slice(0, 16);
          ctx.waitUntil(Promise.resolve().then(() => {
            try {
              env.ANALYTICS.writeDataPoint({
                blobs:   [toolName, callerHash, success ? "ok" : "error"],
                doubles: [latencyMs, chainDepth ?? 0],
                indexes: [toolName],
              });
            } catch (_) { /* telemetry is best-effort; never affect the response */ }
          }));
        }

        return response;
      } catch (e) {
        return Response.json(
          { error: e.message, stack: e.stack },
          { status: 500, headers: CORS_HEADERS }
        );
      }
    }

    return new Response("Not found", { status: 404, headers: CORS_HEADERS });
  },
};

// Exported for the discovery self-test (scripts) and reuse — no runtime effect on the Worker.
export { handleFindTool, handleFindChain, bm25Search, TOOL_INDEX, CHAIN_INDEX };
